//! The generated file tree: server configuration, validation, writing, and checks.
use crate::{ORIGIN, Result, pages};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::Path,
};

/// Uploaded separately with each release; never generated, pruned, or compared.
const PRESERVED: &[&str] = &["downloads"];

#[derive(Default)]
pub struct Tree(BTreeMap<String, Vec<u8>>);

impl Tree {
    pub fn insert(&mut self, path: &str, bytes: Vec<u8>) -> Result<()> {
        if self.0.insert(path.to_owned(), bytes).is_some() {
            return Err(format!("Two outputs were generated for {path}."));
        }
        Ok(())
    }
    pub fn len(&self) -> usize {
        self.0.len()
    }
}

/// Apache configuration, crawler files, and the sitemap.
pub fn server_files() -> Vec<(&'static str, String)> {
    let sitemap: String = pages::INDEXED
        .iter()
        .map(|url| format!("  <url><loc>{ORIGIN}{url}</loc></url>\n"))
        .collect();
    vec![
        (
            ".htaccess",
            format!(
                "# Generated by site/builder (pitty-site). Edit the builder, not this file.\n\
Options -Indexes\n\
DirectoryIndex index.html\n\
ErrorDocument 404 /404.html\n\
\n\
<IfModule mod_rewrite.c>\n\
  RewriteEngine On\n\
  # Honor the visitor protocol Cloudflare forwards, so redirects never loop.\n\
  RewriteCond %{{HTTP:X-Forwarded-Proto}} ^http$ [NC,OR]\n\
  RewriteCond %{{HTTPS}} !=on\n\
  RewriteCond %{{HTTP:X-Forwarded-Proto}} !^https$ [NC]\n\
  RewriteRule ^ {ORIGIN}%{{REQUEST_URI}} [R=301,L,NE]\n\
  RewriteCond %{{HTTP_HOST}} ^www\\. [NC]\n\
  RewriteRule ^ {ORIGIN}%{{REQUEST_URI}} [R=301,L,NE]\n\
  # The original reference page now lives on the download page and in the guide.\n\
  RewriteRule ^install\\.html$ /download/ [R=301,L]\n\
</IfModule>\n\
\n\
<IfModule mod_headers.c>\n\
  Header always set X-Content-Type-Options \"nosniff\"\n\
  Header always set Referrer-Policy \"strict-origin-when-cross-origin\"\n\
  Header always set Permissions-Policy \"camera=(), microphone=(), geolocation=(), payment=(), usb=()\"\n\
  Header always set Cross-Origin-Opener-Policy \"same-origin\"\n\
  Header always set X-Frame-Options \"DENY\"\n\
  Header always set Content-Security-Policy \"frame-ancestors 'none'\"\n\
  Header always set Strict-Transport-Security \"max-age=31536000\"\n\
  # Pages revalidate so releases and instructions appear immediately.\n\
  <FilesMatch \"\\.html$\">\n\
    Header set Cache-Control \"no-cache\"\n\
  </FilesMatch>\n\
</IfModule>\n\
\n\
<IfModule mod_deflate.c>\n\
  AddOutputFilterByType DEFLATE text/html text/css text/javascript text/plain application/javascript application/wasm application/xml image/svg+xml\n\
</IfModule>\n\
\n\
AddType application/wasm .wasm\n\
AddType font/woff2 .woff2\n\
AddType text/javascript .js\n\
AddCharset utf-8 .html .css .js .svg .txt .xml\n\
<FilesMatch \"\\.sha256$\">\n\
  ForceType \"text/plain; charset=utf-8\"\n\
</FilesMatch>\n"
            ),
        ),
        (
            "assets/.htaccess",
            "# Generated by site/builder. Every file here has a content hash in its name.\n\
<IfModule mod_headers.c>\n\
  Header set Cache-Control \"public, max-age=31536000, immutable\"\n\
</IfModule>\n"
                .into(),
        ),
        (
            "robots.txt",
            format!("User-agent: *\nAllow: /\n\nSitemap: {ORIGIN}/sitemap.xml\n"),
        ),
        (
            "sitemap.xml",
            format!(
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n{sitemap}</urlset>\n"
            ),
        ),
    ]
}

fn attribute_values<'a>(html: &'a str, attribute: &str) -> Vec<&'a str> {
    let needle = format!(" {attribute}=\"");
    html.match_indices(&needle)
        .filter_map(|(index, _)| {
            let rest = &html[index + needle.len()..];
            rest.find('"').map(|end| &rest[..end])
        })
        .collect()
}

/// Map a site URL path to the file that serves it.
fn file_for(path: &str) -> String {
    let path = path.trim_start_matches('/');
    if path.is_empty() || path.ends_with('/') {
        format!("{path}index.html")
    } else {
        path.to_owned()
    }
}

/// Unique ids, matching copy targets, and internal links that resolve to a
/// generated file and, when given, an existing fragment.
pub fn validate(tree: &Tree) -> Result<()> {
    let mut ids: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
    let pages: Vec<(&str, &str)> = tree
        .0
        .iter()
        .filter(|(path, _)| path.ends_with(".html"))
        .map(|(path, bytes)| {
            std::str::from_utf8(bytes)
                .map(|html| (path.as_str(), html))
                .map_err(|_| format!("{path} is not UTF-8"))
        })
        .collect::<Result<_>>()?;
    for (path, html) in &pages {
        let set = ids.entry(path).or_default();
        for id in attribute_values(html, "id") {
            if !set.insert(id) {
                return Err(format!("{path}: duplicate id \"{id}\""));
            }
        }
        for target in attribute_values(html, "data-copy")
            .into_iter()
            .chain(attribute_values(html, "data-copy-status"))
        {
            if !set.contains(target) {
                return Err(format!(
                    "{path}: copy control targets missing id \"{target}\""
                ));
            }
        }
        for target in attribute_values(html, "for")
            .into_iter()
            .chain(attribute_values(html, "aria-labelledby"))
            .chain(attribute_values(html, "aria-controls"))
        {
            for id in target.split_whitespace() {
                if !set.contains(id) {
                    return Err(format!(
                        "{path}: a label or control names missing id \"{id}\""
                    ));
                }
            }
        }
    }
    let mut problems = Vec::new();
    for (path, html) in &pages {
        // Meta `content` values are checked only when they are absolute site URLs.
        let absolute = attribute_values(html, "content")
            .into_iter()
            .filter(|value| value.starts_with(ORIGIN));
        for link in attribute_values(html, "href")
            .into_iter()
            .chain(attribute_values(html, "src"))
            .chain(attribute_values(html, "poster"))
            .chain(absolute)
        {
            let link = link.strip_prefix(ORIGIN).unwrap_or(link);
            if !link.starts_with('/') && !link.starts_with('#') {
                continue;
            }
            if link.starts_with("/downloads/") {
                continue;
            }
            let (target, fragment) = link.split_once('#').unwrap_or((link, ""));
            let file = if target.is_empty() {
                (*path).to_owned()
            } else {
                file_for(target)
            };
            if !tree.0.contains_key(&file) {
                problems.push(format!("{path}: link to missing {link}"));
            } else if !fragment.is_empty()
                && !ids
                    .get(file.as_str())
                    .is_some_and(|set| set.contains(fragment))
            {
                problems.push(format!("{path}: link to missing anchor {link}"));
            }
        }
    }
    if problems.is_empty() {
        Ok(())
    } else {
        Err(problems.join("\n"))
    }
}

fn existing_files(website: &Path) -> Result<BTreeSet<String>> {
    fn walk(base: &Path, directory: &Path, found: &mut BTreeSet<String>) -> Result<()> {
        let entries = match fs::read_dir(directory) {
            Ok(entries) => entries,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
            Err(error) => return Err(format!("Cannot read {}: {error}", directory.display())),
        };
        for entry in entries {
            let entry = entry.map_err(|error| error.to_string())?;
            let path = entry.path();
            let relative = path
                .strip_prefix(base)
                .map_err(|error| error.to_string())?
                .to_string_lossy()
                .replace('\\', "/");
            if PRESERVED.contains(&relative.as_str()) || relative.ends_with(".DS_Store") {
                continue;
            }
            let kind = entry.file_type().map_err(|error| error.to_string())?;
            if kind.is_symlink() {
                return Err(format!("Refusing to manage symlink {}", path.display()));
            } else if kind.is_dir() {
                walk(base, &path, found)?;
            } else {
                found.insert(relative);
            }
        }
        Ok(())
    }
    let mut found = BTreeSet::new();
    walk(website, website, &mut found)?;
    Ok(found)
}

pub fn compare(tree: &Tree, website: &Path) -> Result<Vec<String>> {
    let existing = existing_files(website)?;
    let mut differences = Vec::new();
    for (path, bytes) in &tree.0 {
        match fs::read(website.join(path)) {
            Ok(current) if current == *bytes => {}
            Ok(_) => differences.push(format!("  changed  {path}")),
            Err(_) => differences.push(format!("  missing  {path}")),
        }
    }
    for path in existing.difference(&tree.0.keys().cloned().collect()) {
        differences.push(format!("  stale    {path}"));
    }
    Ok(differences)
}

pub fn write(tree: &Tree, website: &Path) -> Result<String> {
    use std::os::unix::fs::PermissionsExt;
    let mut changed = 0;
    for (path, bytes) in &tree.0 {
        let destination = website.join(path);
        if fs::read(&destination).is_ok_and(|current| current == *bytes) {
            continue;
        }
        if let Some(parent) = destination.parent() {
            fs::create_dir_all(parent)
                .map_err(|error| format!("Cannot create {}: {error}", parent.display()))?;
        }
        fs::write(&destination, bytes)
            .map_err(|error| format!("Cannot write {}: {error}", destination.display()))?;
        fs::set_permissions(&destination, fs::Permissions::from_mode(0o644))
            .map_err(|error| error.to_string())?;
        changed += 1;
    }
    let mut removed = 0;
    let wanted: BTreeSet<String> = tree.0.keys().cloned().collect();
    for stale in existing_files(website)?.difference(&wanted) {
        let path = website.join(stale);
        fs::remove_file(&path)
            .map_err(|error| format!("Cannot remove {}: {error}", path.display()))?;
        removed += 1;
        // Remove directories that held only generated files.
        let mut parent = path.parent();
        while let Some(directory) = parent.filter(|d| *d != website) {
            if fs::remove_dir(directory).is_err() {
                break;
            }
            parent = directory.parent();
        }
    }
    Ok(format!(
        "website/: {} files, {changed} written, {removed} removed.",
        tree.len()
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    fn tree(files: &[(&str, &str)]) -> Tree {
        let mut tree = Tree::default();
        for (path, html) in files {
            tree.insert(path, html.as_bytes().to_vec()).unwrap();
        }
        tree
    }
    #[test]
    fn links_and_anchors_must_resolve() {
        let ok = tree(&[
            (
                "index.html",
                r##"<a href="/guide/#tools">x</a><a href="#top" id="top">y</a>"##,
            ),
            (
                "guide/index.html",
                r#"<h2 id="tools">Tools</h2><a href="/downloads/x.tar.gz">z</a>"#,
            ),
        ]);
        assert!(validate(&ok).is_ok());
        let missing = tree(&[("index.html", r#"<a href="/guide/#tools">x</a>"#)]);
        assert!(
            validate(&missing)
                .unwrap_err()
                .contains("missing /guide/#tools")
        );
        let anchor = tree(&[
            ("index.html", r#"<a href="/guide/#nope">x</a>"#),
            ("guide/index.html", r#"<h2 id="tools">Tools</h2>"#),
        ]);
        assert!(validate(&anchor).unwrap_err().contains("anchor"));
    }
    #[test]
    fn ids_are_unique_and_copy_buttons_have_targets() {
        let duplicate = tree(&[("index.html", r#"<p id="a"></p><p id="a"></p>"#)]);
        assert!(validate(&duplicate).unwrap_err().contains("duplicate"));
        let orphan = tree(&[("index.html", r#"<button data-copy="gone">Copy</button>"#)]);
        assert!(validate(&orphan).unwrap_err().contains("gone"));
        let label = tree(&[(
            "index.html",
            r#"<input id="a"><label for="a">A</label><label for="b">B</label>"#,
        )]);
        assert!(validate(&label).unwrap_err().contains("\"b\""));
        let named = tree(&[(
            "index.html",
            r#"<p id="x"></p><div aria-labelledby="x y"></div>"#,
        )]);
        assert!(validate(&named).unwrap_err().contains("\"y\""));
    }
    #[test]
    fn site_urls_map_to_files() {
        assert_eq!(file_for("/"), "index.html");
        assert_eq!(file_for("/guide/"), "guide/index.html");
        assert_eq!(file_for("/assets/a.css"), "assets/a.css");
    }
}
